def square_even_numbers(numbers: list[int]) -> list[int]:
    """Return squared even numbers from the list."""
    return [x**2 for x in numbers if x % 2 == 0]

import re
from collections import Counter

def word_frequency(text: str) -> dict[str, int]:
    """Calculate word frequencies ignoring case and punctuation."""
    words = re.findall(r'\b\w+\b', text.lower())
    return dict(Counter(words))

def clean_transactions(records: list[dict]) -> list[dict]:
    """Filter negative transactions and keep the latest unique record by ID."""
    valid = [r for r in records if r.get('amount', 0) >= 0]
    unique = {r['id']: r for r in valid}
    return sorted(unique.values(), key=lambda x: x.get('timestamp', 0))

def is_valid_ipv4(ip: str) -> bool:
    """Validate if an IP string is a valid IPv4 address."""
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit() or not 0 <= int(part) <= 255:
            return False
    return True
